import{_ as r,c as o,o as n,j as a,Y as s,t as d}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"chcon | x-cmd man (man1) | change file security context","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | chcon - change file security context","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"chcon | x-cmd man (man1) | change file security context"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | chcon - change file security context"}]]},"headers":[],"params":{"isMan":true,"man":"chcon","category":"man1","desc":"change file security context"},"relativePath":"man1/chcon.md","filePath":"man1/[man].md"}'),i={name:"man1/chcon.md"},c={class:"visually-hidden"};function l(t,e,h,g,m,p){return n(),o("div",null,[a("h1",c,d(t.$params.man),1),e[0]||(e[0]=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>chcon - change file security context</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>chcon</strong> [<em>OPTION</em>]... <em>CONTEXT FILE</em>... <br> <strong>chcon</strong> [<em>OPTION</em>]... [<em>-u USER</em>] [<em>-r ROLE</em>] [<em>-l RANGE</em>] [<em>-t TYPE</em>] <em>FILE</em>... <br> <strong>chcon</strong> [<em>OPTION</em>]... <em>--reference=RFILE FILE</em>...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Change the SELinux security context of each FILE to CONTEXT. With <strong>--reference</strong>, change the security context of each FILE to that of RFILE.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>--dereference</strong></dt><dd>affect the referent of each symbolic link (this is the default), rather than the symbolic link itself</dd><dt><strong>-h</strong>, <strong>--no-dereference</strong></dt><dd>affect symbolic links instead of any referenced file</dd><dt><strong>-u</strong>, <strong>--user</strong>=<em>USER</em></dt><dd>set user USER in the target security context</dd><dt><strong>-r</strong>, <strong>--role</strong>=<em>ROLE</em></dt><dd>set role ROLE in the target security context</dd><dt><strong>-t</strong>, <strong>--type</strong>=<em>TYPE</em></dt><dd>set type TYPE in the target security context</dd><dt><strong>-l</strong>, <strong>--range</strong>=<em>RANGE</em></dt><dd>set range RANGE in the target security context</dd><dt><strong>--no-preserve-root</strong></dt><dd>do not treat &#39;/&#39; specially (the default)</dd><dt><strong>--preserve-root</strong></dt><dd>fail to operate recursively on &#39;/&#39;</dd><dt><strong>--reference</strong>=<em>RFILE</em></dt><dd>use RFILE&#39;s security context rather than specifying a CONTEXT value</dd><dt><strong>-R</strong>, <strong>--recursive</strong></dt><dd>operate on files and directories recursively</dd><dt><strong>-v</strong>, <strong>--verbose</strong></dt><dd>output a diagnostic for every file processed</dd></dl><p>The following options modify how a hierarchy is traversed when the <strong>-R</strong> option is also specified. If more than one is specified, only the final one takes effect.</p><dl><dt><strong>-H</strong></dt><dd>if a command line argument is a symbolic link to a directory, traverse it</dd><dt><strong>-L</strong></dt><dd>traverse every symbolic link to a directory encountered</dd><dt><strong>-P</strong></dt><dd>do not traverse any symbolic links (default)</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Russell Coker and Jim Meyering.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/chcon%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/chcon\\</a>&gt; <br> or available locally via: info &#39;(coreutils) chcon invocation&#39;</p>',18))])}const y=r(i,[["render",l]]);export{f as __pageData,y as default};
